// Package hashdict builds, saves and loads a combined dictionary of words.
// Every word is stored as a 64-bit hash in a sorted array, together with
// flags that tell which dictionaries contain the word. One lookup returns
// all dictionaries of a word.
//
// The dictionary is generated by gndict (github.com/gnames/gndict), which
// imports this package, and loaded by the dict package. This package must
// not depend on the embedded dictionary data.
//
// # File format
//
//	magic          4 bytes, "GNHD"
//	version        uint16, little endian, FormatVersion
//	canary count   uint16, little endian
//	canaries       for each: uint16 length, then the word's bytes
//	word count     uint32, little endian
//	hashes         word count × uint64, little endian, sorted ascending
//	flags          word count × uint16, little endian
//
// Canaries are words the dictionary was built from. Load checks that the
// dictionary still finds all of them. This catches files that are not
// compatible with the current code, for example after a change of the hash
// function.
package hashdict

import (
	"bufio"
	"bytes"
	"encoding/binary"
	"encoding/csv"
	"errors"
	"fmt"
	"io"
	"slices"
)

// FormatVersion is the version of the file format. Increase it whenever
// saved dictionaries become incompatible with the code: a change of the
// header, of the hash function, or of the meaning of flags.
const FormatVersion uint16 = 1

// canaryNum is the maximum number of canary words stored in a file.
const canaryNum = 8

// indexBits is the number of top hash bits used by the prefix index.
// With 2^18 buckets and about 2.6 million words a binary search covers
// about 10 hashes.
const indexBits = 18

var magic = []byte("GNHD")

// ErrIncompatible means that a dictionary file cannot be used with this
// version of the code. Such files have to be regenerated.
var ErrIncompatible = errors.New("incompatible dictionary file")

// Flags is a bit set of dictionaries that contain a word.
type Flags uint16

// Dictionaries that can contain a word.
const (
	InGenus Flags = 1 << iota
	InAmbigGenus
	InUninomial
	InAmbigUninomial
	NotInUninomial
	CommonWord
	InSpecies
	InAmbigSpecies
	NotInSpecies
	InAmbigGenusSp
)

// Has is true if all flags of f2 are set in f.
func (f Flags) Has(f2 Flags) bool {
	return f&f2 == f2
}

// Dict is a sorted array of word hashes with flags for each hash.
type Dict struct {
	hashes   []uint64
	flags    []Flags
	start    []uint32
	canaries []string
}

// Lookup returns the flags of a word, or 0 if the word is not in the
// dictionary. A word that is not in the dictionary gets flags of another
// word only if their 64-bit hashes are equal, which is very unlikely.
func (d *Dict) Lookup(word string) Flags {
	h := Hash(word)
	p := h >> (64 - indexBits)
	lo, hi := d.start[p], d.start[p+1]
	if i, ok := slices.BinarySearch(d.hashes[lo:hi], h); ok {
		return d.flags[int(lo)+i]
	}
	return 0
}

// Len returns the number of words in the dictionary.
func (d *Dict) Len() int {
	return len(d.hashes)
}

// Builder collects words and their flags for a new dictionary.
type Builder struct {
	words map[string]Flags
}

// NewBuilder creates an empty Builder.
func NewBuilder() *Builder {
	return &Builder{words: make(map[string]Flags)}
}

// AddWord adds flags to a word.
func (b *Builder) AddWord(word string, f Flags) {
	b.words[word] |= f
}

// Add adds flags to the words from the first column of a CSV file.
func (b *Builder) Add(r io.Reader, f Flags) error {
	reader := csv.NewReader(r)
	for {
		v, err := reader.Read()
		if err == io.EOF {
			return nil
		}
		if err != nil {
			return err
		}
		b.AddWord(v[0], f)
	}
}

// Build creates a dictionary from the collected words. It fails if two
// different words have the same hash.
func (b *Builder) Build() (*Dict, error) {
	type hf struct {
		hash  uint64
		flags Flags
		word  string
	}
	all := make([]hf, 0, len(b.words))
	for w, f := range b.words {
		all = append(all, hf{Hash(w), f, w})
	}
	slices.SortFunc(all, func(a, b hf) int {
		switch {
		case a.hash < b.hash:
			return -1
		case a.hash > b.hash:
			return 1
		}
		return 0
	})

	d := &Dict{
		hashes: make([]uint64, len(all)),
		flags:  make([]Flags, len(all)),
	}
	for i, v := range all {
		if i > 0 && v.hash == all[i-1].hash {
			return nil, fmt.Errorf("hash collision: %q and %q",
				all[i-1].word, v.word)
		}
		d.hashes[i] = v.hash
		d.flags[i] = v.flags
	}
	// canaries are the words with the smallest hashes: a deterministic
	// choice spread over the whole alphabet.
	for _, v := range all[:min(canaryNum, len(all))] {
		if len(v.word) <= 1<<16-1 {
			d.canaries = append(d.canaries, v.word)
		}
	}
	d.buildIndex()
	return d, nil
}

// buildIndex sets start offsets of every hash prefix.
func (d *Dict) buildIndex() {
	d.start = make([]uint32, 1<<indexBits+1)
	for _, h := range d.hashes {
		d.start[h>>(64-indexBits)+1]++
	}
	for i := 1; i < len(d.start); i++ {
		d.start[i] += d.start[i-1]
	}
}

// Save writes the dictionary to w.
func (d *Dict) Save(w io.Writer) error {
	bw := bufio.NewWriter(w)
	_, _ = bw.Write(magic)
	_ = binary.Write(bw, binary.LittleEndian, FormatVersion)
	_ = binary.Write(bw, binary.LittleEndian, uint16(len(d.canaries)))
	for _, c := range d.canaries {
		_ = binary.Write(bw, binary.LittleEndian, uint16(len(c)))
		_, _ = bw.WriteString(c)
	}
	_ = binary.Write(bw, binary.LittleEndian, uint32(len(d.hashes)))
	buf := make([]byte, 8)
	for _, h := range d.hashes {
		binary.LittleEndian.PutUint64(buf, h)
		_, _ = bw.Write(buf)
	}
	for _, f := range d.flags {
		binary.LittleEndian.PutUint16(buf, uint16(f))
		_, _ = bw.Write(buf[:2])
	}
	return bw.Flush()
}

// Load reads a dictionary saved by Save. It returns an error wrapping
// ErrIncompatible if the file was made by an incompatible version of the
// code.
func Load(data []byte) (*Dict, error) {
	r := bytes.NewReader(data)
	canaries, err := readHeader(r)
	if err != nil {
		return nil, err
	}
	var num uint32
	if err = binary.Read(r, binary.LittleEndian, &num); err != nil {
		return nil, fmt.Errorf("cannot read dictionary header: %w", err)
	}
	rest := data[len(data)-r.Len():]
	if len(rest) != int(num)*10 {
		return nil, fmt.Errorf("%w: expected %d words, got %d bytes",
			ErrIncompatible, num, len(rest))
	}

	d := &Dict{
		hashes:   make([]uint64, num),
		flags:    make([]Flags, num),
		canaries: canaries,
	}
	for i := range d.hashes {
		d.hashes[i] = binary.LittleEndian.Uint64(rest[i*8:])
	}
	rest = rest[num*8:]
	for i := range d.flags {
		d.flags[i] = Flags(binary.LittleEndian.Uint16(rest[i*2:]))
	}
	if !slices.IsSorted(d.hashes) {
		return nil, fmt.Errorf("%w: hashes are not sorted", ErrIncompatible)
	}
	d.buildIndex()

	for _, c := range d.canaries {
		if d.Lookup(c) == 0 {
			return nil, fmt.Errorf("%w: dictionary misses canary word %q",
				ErrIncompatible, c)
		}
	}
	return d, nil
}

func readHeader(r io.Reader) ([]string, error) {
	m := make([]byte, len(magic))
	if _, err := io.ReadFull(r, m); err != nil {
		return nil, fmt.Errorf("cannot read dictionary header: %w", err)
	}
	if !bytes.Equal(m, magic) {
		return nil, fmt.Errorf("%w: not a gnfinder dictionary", ErrIncompatible)
	}

	var version, num uint16
	if err := binary.Read(r, binary.LittleEndian, &version); err != nil {
		return nil, fmt.Errorf("cannot read dictionary header: %w", err)
	}
	if version != FormatVersion {
		return nil, fmt.Errorf("%w: format version %d, expected %d",
			ErrIncompatible, version, FormatVersion)
	}

	if err := binary.Read(r, binary.LittleEndian, &num); err != nil {
		return nil, fmt.Errorf("cannot read dictionary header: %w", err)
	}
	res := make([]string, num)
	for i := range res {
		var l uint16
		if err := binary.Read(r, binary.LittleEndian, &l); err != nil {
			return nil, fmt.Errorf("cannot read dictionary header: %w", err)
		}
		b := make([]byte, l)
		if _, err := io.ReadFull(r, b); err != nil {
			return nil, fmt.Errorf("cannot read dictionary header: %w", err)
		}
		res[i] = string(b)
	}
	return res, nil
}

// Path is the path of the dictionary file relative to the data directory.
const Path = "hashdict/dict.bin"

// Hash converts a word to a 64-bit FNV-1a hash. Dictionaries built and
// queried by this package always use the same function, so saved
// dictionaries stay valid. Changing it requires a new FormatVersion.
func Hash(word string) uint64 {
	const (
		offset = 14695981039346656037
		prime  = 1099511628211
	)
	h := uint64(offset)
	for i := 0; i < len(word); i++ {
		h ^= uint64(word[i])
		h *= prime
	}
	return h
}
